"""Stagnation density / static density ratio.

    Arguments:
        M (scalar): Mach number [units: dimensionless].
        gamma (scalar): Heat capacity ratio [units: dimensionless].

    Returns:
        scalar: the stagnation density ratio :math:`\\rho_0 / \\rho` [units: dimensionless].
    """
def stag_density_ratio(M: Any, gamma: Any) -> object {
    return ((1 + (((gamma - 1) / 2) * (M ** 2))) ** (1 / (gamma - 1)));
}

"""
    See setCounters() / getCounters() methods in IJ source, ij/gui/PointRoi.java.
    """
def get_counter(data: Any, base: Any) -> object {
    b0 = data[base];
    b1 = data[(base + 1)];
    b2 = data[(base + 2)];
    b3 = data[(base + 3)];
    counter = b3;
    position = (b1 << 8) + b2;
    return (counter, position);
}

"""
    Given an entity_id, rename it to something else. Helpful if ids changed
    during the course of history and you want to quickly merge the data. Beware
    that no further adjustment is done, also no checks whether the referred
    sensors are even compatible.
    """
def rename_entity_id(old_name: Any) -> object {
    rename_table = {"sensor.old_entity_name": "sensor.new_entity_name"};
    if (old_name in rename_table) {
        return rename_table[old_name];
    }
    return old_name;
}

